import{_ as e,o as s,c as p,a2 as l}from"./chunks/framework.DPTp4bo7.js";const k=JSON.parse('{"title":"1.2 采用阻塞生产形式有什么好处","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}]]},"headers":[],"relativePath":"zh/1-2-what-are-the-benefits-of-blocking-based-production.md","filePath":"zh/page-vjw47WlrDGyaYlemKyfnH8.md"}'),r={name:"zh/1-2-what-are-the-benefits-of-blocking-based-production.md"};function n(t,a,o,i,c,d){return s(),p("div",null,[...a[0]||(a[0]=[l('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-2-采用阻塞生产形式有什么好处" aria-hidden="true"></span><h1 id="_1-2-采用阻塞生产形式有什么好处" tabindex="-1">1.2 采用阻塞生产形式有什么好处 <a class="header-anchor" href="#_1-2-采用阻塞生产形式有什么好处" aria-label="Permalink to &quot;1\\.2 采用阻塞生产形式有什么好处&quot;">​</a></h1><blockquote><p>源页面 ID：<code>vjw47WlrDGyaYlemKyfnH8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>相对于传统的定速生产，合理的阻塞生产设计能为进阶的生产需求带来很大的便利。例如：</p><ol><li><p><span class="mark-purple">我想先生产</span><span class="mark-purple"><u>一仓库的紫晶瓶</u></span><span class="mark-purple">，然后再开始生产</span><span class="mark-purple"><u>高晶瓶</u></span><span class="mark-purple">。</span></p></li><li><p><span class="mark-purple">我想</span><span class="mark-purple"><u>保证仓库内一直有钢零件随用随取</u></span><span class="mark-purple">，在不用时也不浪费钢的产能，都去做谷地电池。</span></p></li><li><p><span class="mark-purple">我想让赤铜块</span><span class="mark-purple"><u>先做赤铜零件</u></span><span class="mark-purple">，为了防止铜块爆仓堵住污水，赤铜零件做满后需要</span><span class="mark-purple"><u>让赤铜块继续做赤铜装备元件</u></span><span class="mark-purple">。</span></p></li><li><p><span class="mark-purple">我想让息壤</span><span class="mark-purple"><u>优先满足中容武陵电池</u></span><span class="mark-purple">的生产需求，多余的息壤再做别的，这样即使我偶尔从谷地搬运多余的源石粉末到武陵，也能够消耗掉。</span></p></li><li><p><span class="mark-purple">我想</span><span class="mark-purple"><u>把原材料全部用完做成成品</u></span><span class="mark-purple">，即使成品产速为一个复杂分数，使用自适应方案也能自动达到这一产速。</span></p></li><li><p><span class="mark-purple">我不想让转化机白吃息壤，我需要它有多少原料给多少息壤</span></p></li></ol><p>以上这些常见的进阶生产需求，如果采用传统的直接生产方案，往往需要进行一定的手工调整，如调整机器生产配置等，不仅麻烦，还容易出现忘记操作，或者无法在合适的时间上线而导致材料浪费乃至停电的情况。阻塞生产则通过特定的产线设计，让生产方案得以自动切换，从而在无需操作的情况下实现此类目标，减少我们的操作负担。</p><p><a href="/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 那我问你，什么是阻塞生产</a></p><p><a href="/endfield-skydoc/zh/1-3-glossary">1.3 术语表（我自己也没法完全定义清楚，不看也罢）</a></p></div>',1)])])}const h=e(r,[["render",n]]);export{k as __pageData,h as default};
